queries.query:
query ZubatEvolutionTypes($name: String!, $isDefault: Boolean!, $chainLimit: Int!, $typeLimit: Int!) {
  pokemonspecies(where: {name: {_eq: $name}}, limit: 1) {
    id
    name
    evolutionchain {
      id
      pokemonspecies(limit: $chainLimit, order_by: {id: asc}) {
        id
        name
        pokemons(where: {is_default: {_eq: $isDefault}}, limit: 1) {
          id
          name
          pokemontypes(limit: $typeLimit, order_by: {slot: asc}) {
            slot
            type { id name }
          }
        }
      }
    }
  }
}

query GetZubatEvolution($name: String!, $speciesLimit: Int!, $typeLimit: Int!) {
  pokemonspecies(where: {name: {_eq: $name}}, limit: $speciesLimit) {
    id
    name
    evolutionchain {
      id
      pokemonspecies(order_by: {id: asc}, limit: $speciesLimit) {
        id
        name
        pokemons(where: {is_default: {_eq: true}}, limit: 1) {
          id
          name
          pokemontypes(order_by: {slot: asc}, limit: $typeLimit) {
            slot
            type {
              id
              name
            }
          }
        }
      }
    }
  }
}

query GetStarterFinalEvolutions($names: [String!]!, $limit: Int!) {
  pokemon(where: {name: {_in: $names}, is_default: {_eq: true}}, limit: $limit) {
    id
    name
    pokemontypes(limit: 5) {
      slot
      type {
        id
        name
      }
    }
  }
}

query ResolveAnswerEntities($names: [String!]!, $limit: Int!) {
  ability(where: {name: {_in: $names}}, order_by: {id: asc}, limit: $limit) { id name }
  item(where: {name: {_in: $names}}, order_by: {id: asc}, limit: $limit) { id name }
  move(where: {name: {_in: $names}}, order_by: {id: asc}, limit: $limit) { id name }
  pokemon(where: {name: {_in: $names}}, order_by: {id: asc}, limit: $limit) { id name }
}

query KantoStarterFinalEvolutions($speciesIds: [Int!]!, $isDefault: Boolean!, $limit: Int!, $typeLimit: Int!) {
  pokemon(where: {pokemon_species_id: {_in: $speciesIds}, is_default: {_eq: $isDefault}}, order_by: {id: asc}, limit: $limit) {
    id
    name
    pokemon_species_id
    pokemontypes(limit: $typeLimit, order_by: {slot: asc}) {
      slot
      type {
        name
      }
    }
  }
}

query Original151Intimidate($maxNationalDex: Int!, $abilityName: String!, $isDefault: Boolean!, $limit: Int!) {
  pokemonspecies(where: {
    id: {_lte: $maxNationalDex}
    pokemons: {
      is_default: {_eq: $isDefault}
      pokemonabilities: {ability: {name: {_eq: $abilityName}}}
    }
  }, order_by: {id: asc}, limit: $limit) {
    id
    name
    pokemons(where: {is_default: {_eq: $isDefault}}, limit: 1) {
      id
      name
      pokemonabilities(where: {ability: {name: {_eq: $abilityName}}}, limit: 3) {
        ability { id name }
        is_hidden
        slot
      }
    }
  }
}

query GetGen1IntimidatePokemon($abilityName: String!, $maxSpeciesId: Int!, $limit: Int!) {
  pokemonability(
    where: {
      ability: {name: {_eq: $abilityName}}
      pokemon: {
        pokemon_species_id: {_lte: $maxSpeciesId}
        is_default: {_eq: true}
      }
    }
    order_by: {pokemon_id: asc}
    limit: $limit
  ) {
    pokemon {
      id
      name
      pokemon_species_id
      pokemonspecy {
        id
        name
      }
    }
    is_hidden
    slot
  }
}

