query ShedinjaAbility($name: String!, $language: String!, $limit: Int!, $flavorLimit: Int!) {
  pokemon(where: {name: {_eq: $name}}, limit: $limit) {
    id
    name
    pokemonabilities(order_by: {id: asc}, limit: $limit) {
      is_hidden
      ability {
        id
        name
        abilityeffecttexts(where: {language: {iso639: {_eq: $language}}}, limit: $limit) {
          effect
          short_effect
        }
        abilityflavortexts(where: {language: {iso639: {_eq: $language}}}, order_by: {version_group_id: desc}, limit: $flavorLimit) {
          flavor_text
          version_group_id
        }
      }
    }
  }
}

